import { randomUUID } from 'node:crypto';

/**
 * Request ids are always generated by the server. A client-supplied
 * X-Request-Id (survivor app, partner dashboard or anyone else) is never
 * adopted, logged or stored: request ids end up in case events and audit
 * rows, so they must not carry values a client or partner chose.
 */
export function generateRequestId(): string {
  return randomUUID();
}

/** Fastify options for every API instance: ignore request-id headers, generate ids server-side. */
export const REQUEST_ID_OPTIONS = {
  requestIdHeader: false,
  genReqId: () => generateRequestId(),
} as const;
